ip small{font-size:8px;display:block;color:#a9b3a5;margin-top:3px;letter-spacing:.8px}.quest-card{position:absolute;right:34px;top:98px;width:255px;padding:16px;background:rgba(17,29,25,.83);border:1px solid rgba(238,231,207,.19);backdrop-filter:blur(10px);box-shadow:0 10px 40px rgba(0,0,0,.12)}.quest-top{display:flex;justify-content:space-between;align-items:center}.eyebrow{font:500 9px var(--display);letter-spacing:1.8px;color:#dfbd78}.quest-count{font:400 9px var(--display);letter-spacing:1px;color:#9da99c}.quest-card h2{font:500 19px var(--display);letter-spacing:1.4px;margin:9px 0 4px}.quest-card p{font-size:10px;line-height:1.6;color:#bbc4b6;margin:0 0 14px}.quest-objective{display:flex;gap:8px;align-items:center;border-top:1px solid var(--line);padding-top:12px;font-size:10px}.objective-dot{width:7px;height:7px;border:1px solid #e5b96e;border-radius:50%}.objective-progress{margin-left:auto;color:#e7c781;font:500 10px var(--display)}.journal-link{border:0;background:transparent;padding:12px 0 0;color:#d9bd82;font:500 9px var(--display);letter-spacing:1.4px;cursor:pointer}.journal-link span{margin-left:5px}.bottom-left{position:absolute;left:34px;bottom:30px;z-index:2;display:flex;gap:7px;align-items:center}.round-button{height:39px;width:39px;background:rgba(17,29,25,.82);border:1px solid rgba(238,231,207,.26);font-size:17px;cursor:pointer;transition:.2s}.round-button:hover{border-color:var(--gold);color:var(--gold);transform:translateY(-2px)}.bottom-label{font:500 9px var(--display);letter-spacing:1.6px;color:#d8dfce;margin-left:6px}.hotbar{position:absolute;z-index:2;bottom:22px;left:50%;transform:translateX(-50%);display:flex;gap:5px;align-items:center}.hotbar-slot{position:relative;width:55px;height:57px;background:rgba(15,28,24,.78);border:1px solid rgba(238,231,207,.24);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px}.hotbar-slot.active{border-color:#dfbd78;background:rgba(80,67,39,.63);box-shadow:0 0 16px rgba(229,18