lay:flex}.panel{position:relative;width:min(620px,90vw);max-height:82vh;overflow:auto;background:rgba(19,31,26,.97);border:1px solid rgba(229,185,110,.38);box-shadow:0 20px 80px #07100c;padding:35px 38px}.panel-close{position:absolute;right:17px;top:12px;border:0;background:none;color:#e9dfc4;font-size:25px;cursor:pointer}.panel h2{font:500 29px var(--display);letter-spacing:2px;margin:9px 0 4px}.panel-sub{font-size:11px;color:#aab5a5;margin:0 0 23px}.panel-tabs{display:flex;gap:7px;border-bottom:1px solid var(--line);margin-bottom:14px;flex-wrap:wrap}.panel-tab{background:none;border:0;border-bottom:2px solid transparent;padding:8px 9px;color:#9eaa9b;font:500 9px var(--display);letter-spacing:1px;cursor:pointer}.panel-tab.active{color:#edce8b;border-color:#d6b66e}.item-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.item-card{min-height:84px;border:1px solid rgba(238,231,207,.13);background:rgba(255,255,255,.025);padding:11px;display:flex;gap:9px;align-items:center;cursor:pointer;transition:.2s}.item-card:hover{border-color:rgba(229,185,110,.55);background:rgba(229,185,110,.07)}.item-emoji{font-size:22px}.item-card strong{display:block;font:500 11px var(--display);letter-spacing:.5px}.item-card small{display:block;margin-top:4px;font-size:9px;color:#a7b2a1}.recipe-list{display:grid;gap:8px}.recipe{border:1px solid rgba(238,231,207,.14);display:flex;align-items:center;padding:12px;gap:12px;background:rgba(255,255,255,.025)}.recipe-icon{font-size:23px;width:34px}.recipe-info{flex:1}.recipe-info b{display:block;font:500 12px var(--display);letter-spacing:.5px}.recipe-info small{color:#a7b2a1;display:block;font-size:9px;margin-top:4px}.craft-button{background:#d6b66e;border:0;color:#1a261f;font:600 9px var(--display);letter-spacing:1px;padding:9px 13px;cursor:pointer}.craft-button:disabled{opacity:.35;cursor:not-allowed}.stat-line{display:flex;align-items:center;gap:12px;margin:14px 0}.stat-line label{font:500 10px var(--display);letter-spacing:1px;width:130px}.stat-line input{flex:1;accent-color:#d6b66e}.panel-note{margin-top:20px;color:#93a08f;font-size:10px;line-height:1.6}.pause-overlay{position:absolute;z-index:7;inset:0;background:rgba(8,16,13,.67);backdrop-filter:blur(5px);display:none;align-items:center;justify-content:center}.pause-overlay.open{display:flex}.pause-card{text-align:center;width:330px;padding:34px;background:rgba(19,31,26,.97);border:1px solid rgba(229,185,110,.35)}.pause-card h2{font:500 40px var(--display);letter-spacing:4px;margin:8px 0}.pause-card p{font-size:11px;color:#aab5a5;margin:0 0 21px}.pause-card .primary-button{margin:auto}.pause-card .text-button{margin:auto}.damage-flash{position:absolute;z-index:4;inset:0;pointer-events:none;box-shadow:inset 0 0 100px rgba(195,52,40,0);transition:box-shadow .3s}.damage-flash.hit{box-shadow:inset 0 0 100px rgba(195,52,40,.55)}.mobile-controls{display:none}
